The main issue is in your session creation flow, and it’s being hidden by this line:

```ts
catch (err) {
  console.error(err);
  return null;
}
```

Your `createWorkoutSession()` function is failing, but the UI only sees `null` and shows “Unable to start workout session”.

The most likely cause is a database migration problem. Your `getDatabase()` function creates the `user_profiles` table differently depending on the database version:

```ts
if (currentVersion < 1) {
  await db.execAsync(`
    CREATE TABLE IF NOT EXISTS user_profiles (
      id TEXT PRIMARY KEY NOT NULL,
      email TEXT NOT NULL UNIQUE,
      first_name TEXT,
      last_name TEXT,
      date_of_birth TEXT,
      gender TEXT,
      height REAL,
      weight REAL,
      fitness_level TEXT,
      fitness_goal TEXT,
      workouts_per_week INTEGER,
      workout_duration INTEGER,
      dietary_preferences TEXT,
      medical_conditions TEXT,
      onboarding_completed INTEGER DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
  `);

  await db.execAsync(`
    CREATE TABLE IF NOT EXISTS workout_sessions (
      id TEXT PRIMARY KEY NOT NULL,
      profile_id TEXT NOT NULL,
      workout_type TEXT NOT NULL,
      started_at TEXT NOT NULL,
      completed_at TEXT,
      duration INTEGER,
      calories_burned REAL,
      notes TEXT,
      FOREIGN KEY (profile_id) REFERENCES user_profiles(id)
    );
  `);

  await db.execAsync(`
    CREATE TABLE IF NOT EXISTS workout_exercises (
      id TEXT PRIMARY KEY NOT NULL,
      session_id TEXT NOT NULL,
      exercise_name TEXT NOT NULL,
      sets INTEGER NOT NULL,
      reps INTEGER NOT NULL,
      weight REAL,
      rest_time INTEGER,
      notes TEXT,
      FOREIGN KEY (session_id) REFERENCES workout_sessions(id)
    );
  `);
}

if (currentVersion < 2) {
  await addColumnIfMissing(db, "user_profiles", "profile_visibility", "TEXT NOT NULL DEFAULT 'private'");
  await addColumnIfMissing(db, "user_profiles", "onboarding_completed", "INTEGER NOT NULL DEFAULT 0");
}
```

The problem is that `onboarding_completed` already exists in the original `CREATE TABLE`, so this migration may still be okay because `addColumnIfMissing()` checks for it. However, existing databases can still have incomplete migrations or missing tables.

First, change `createWorkoutSession()` so you can see the real error:

```ts
export async function createWorkoutSession(
  workoutType: string,
  profileId?: string
): Promise<WorkoutSession | null> {
  try {
    const db = await getDatabase();

    let currentProfileId = profileId;

    if (!currentProfileId) {
      const profile = await getCurrentUserProfile();
      currentProfileId = profile?.id;
    }

    if (!currentProfileId) {
      throw new Error("No profile found for workout session");
    }

    const session: WorkoutSession = {
      id: `session_${Date.now()}`,
      profile_id: currentProfileId,
      workout_type: workoutType,
      started_at: new Date().toISOString(),
      completed_at: null,
      duration: null,
      calories_burned: null,
      notes: null,
    };

    await db.runAsync(
      `INSERT INTO workout_sessions (
        id,
        profile_id,
        workout_type,
        started_at,
        completed_at,
        duration,
        calories_burned,
        notes
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        session.id,
        session.profile_id,
        session.workout_type,
        session.started_at,
        session.completed_at,
        session.duration,
        session.calories_burned,
        session.notes,
      ]
    );

    return session;
  } catch (err) {
    console.error("createWorkoutSession failed:", err);
    throw err;
  }
}
```

Then change your `startSession()` function so the actual database error is visible:

```ts
const startSession = async () => {
  try {
    if (!selectedWorkout) {
      Alert.alert("Select a workout", "Please select a workout before starting.");
      return;
    }

    const profile = await getCurrentUserProfile();

    if (!profile?.id) {
      Alert.alert(
        "Profile required",
        "Please complete your profile before starting a workout."
      );
      return;
    }

    const session = await createWorkoutSession(
      selectedWorkout.type,
      profile.id
    );

    if (!session) {
      Alert.alert(
        "Unable to start workout",
        "The workout session could not be created."
      );
      return;
    }

    setActiveSession(session);
    setIsWorkoutStarted(true);
  } catch (error) {
    console.error("startSession failed:", error);

    Alert.alert(
      "Unable to start workout",
      error instanceof Error ? error.message : "Unknown database error"
    );
  }
};
```

Also make sure your database always creates the workout tables, even when the database already exists. Replace your migration code with this more reliable version:

```ts
export async function getDatabase() {
  const db = await SQLite.openDatabaseAsync("fitness.db");

  await db.execAsync(`
    PRAGMA foreign_keys = ON;
  `);

  await db.execAsync(`
    CREATE TABLE IF NOT EXISTS user_profiles (
      id TEXT PRIMARY KEY NOT NULL,
      email TEXT NOT NULL UNIQUE,
      first_name TEXT,
      last_name TEXT,
      date_of_birth TEXT,
      gender TEXT,
      height REAL,
      weight REAL,
      fitness_level TEXT,
      fitness_goal TEXT,
      workouts_per_week INTEGER,
      workout_duration INTEGER,
      dietary_preferences TEXT,
      medical_conditions TEXT,
      onboarding_completed INTEGER NOT NULL DEFAULT 0,
      profile_visibility TEXT NOT NULL DEFAULT 'private',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS workout_sessions (
      id TEXT PRIMARY KEY NOT NULL,
      profile_id TEXT NOT NULL,
      workout_type TEXT NOT NULL,
      started_at TEXT NOT NULL,
      completed_at TEXT,
      duration INTEGER,
      calories_burned REAL,
      notes TEXT,
      FOREIGN KEY (profile_id) REFERENCES user_profiles(id)
    );

    CREATE TABLE IF NOT EXISTS workout_exercises (
      id TEXT PRIMARY KEY NOT NULL,
      session_id TEXT NOT NULL,
      exercise_name TEXT NOT NULL,
      sets INTEGER NOT NULL,
      reps INTEGER NOT NULL,
      weight REAL,
      rest_time INTEGER,
      notes TEXT,
      FOREIGN KEY (session_id) REFERENCES workout_sessions(id)
    );
  `);

  await addColumnIfMissing(
    db,
    "user_profiles",
    "profile_visibility",
    "TEXT NOT NULL DEFAULT 'private'"
  );

  await addColumnIfMissing(
    db,
    "user_profiles",
    "onboarding_completed",
    "INTEGER NOT NULL DEFAULT 0"
  );

  return db;
}
```

Your `addColumnIfMissing()` helper should look like this:

```ts
async function addColumnIfMissing(
  db: SQLite.SQLiteDatabase,
  tableName: string,
  columnName: string,
  columnDefinition: string
) {
  const columns = await db.getAllAsync<{ name: string }>(
    `PRAGMA table_info(${tableName})`
  );

  const exists = columns.some((column) => column.name === columnName);

  if (!exists) {
    await db.execAsync(
      `ALTER TABLE ${tableName} ADD COLUMN ${columnName} ${columnDefinition}`
    );
  }
}
```

One more possible issue is that `getActiveWorkoutSession()` may be returning an old active session. If your screen automatically checks for an active session on mount, it may prevent a new one from being started.

Make sure it only considers a session active when `completed_at` is null:

```ts
export async function getActiveWorkoutSession(
  profileId: string
): Promise<WorkoutSession | null> {
  const db = await getDatabase();

  return await db.getFirstAsync<WorkoutSession>(
    `
      SELECT *
      FROM workout_sessions
      WHERE profile_id = ?
        AND completed_at IS NULL
      ORDER BY started_at DESC
      LIMIT 1
    `,
    [profileId]
  );
}
```

When finishing a workout, update `completed_at`:

```ts
export async function completeWorkoutSession(
  sessionId: string,
  duration: number,
  caloriesBurned?: number,
  notes?: string
) {
  const db = await getDatabase();

  await db.runAsync(
    `
      UPDATE workout_sessions
      SET
        completed_at = ?,
        duration = ?,
        calories_burned = ?,
        notes = ?
      WHERE id = ?
    `,
    [
      new Date().toISOString(),
      duration,
      caloriesBurned ?? null,
      notes ?? null,
      sessionId,
    ]
  );
}
```

For testing, uninstall and reinstall the app or clear the local database. Existing local databases may still have a broken schema from the earlier migration.

The most important immediate change is to replace:

```ts
catch (err) {
  console.error(err);
  return null;
}
```

with:

```ts
catch (err) {
  console.error("createWorkoutSession failed:", err);
  throw err;
}
```

That will reveal whether the actual problem is:

```text
no such table: workout_sessions
```

```text
no such column: profile_visibility
```

```text
FOREIGN KEY constraint failed
```

or:

```text
No profile found for workout session
```

Once the error is visible, the database migration and profile lookup changes above should resolve the issue.

